const pageBannerImages={home:'office',stationery:'catalogue-range',business:'business',government:'government-bulk',schools:'schools-packs',about:'about',contact:'contact',faq:'help',privacy:'privacy',upload:'procurement',quote:'procurement',basket:'catalogue'};
function applyPageBanner(route){const banner=main.querySelector('.catalogue-heading,.buyer-intro,.page-hero,.shop-hero');if(!banner)return;const subject=pageBannerImages[route]||'office';banner.classList.add('page-banner');if(['business','government','schools','about'].includes(route))banner.classList.add('matched-catalogue-banner');banner.dataset.banner=subject;banner.style.setProperty('--banner-image',`url("images/${subject}-banner-v1.webp")`)}
